"""Evaluate sandbox runs: score per field, timings, model/browser trouble, evidence digest, decision path.

Usage: python3 evalruns.py <run_id> [<run_id> ...]
"""
import collections
import json
import subprocess
import sys


def sh(*args: str) -> str:
    return subprocess.run(args, capture_output=True, text=True, timeout=120).stdout


def events(run: str) -> list[dict]:
    out = []
    for line in sh("atira", "logs", run, "--json").splitlines():
        try:
            item = json.loads(line)
        except ValueError:
            continue
        for part in str(item.get("text", "")).splitlines():
            i = part.find("{")
            if i < 0:
                continue
            try:
                d = json.loads(part[i:])
            except ValueError:
                continue
            if isinstance(d, dict) and "event" in d:
                out.append(d)
    return out


def lost_points(breakdown: dict) -> list[str]:
    lost = []
    for key, value in breakdown.items():
        if key == "positions":
            for p in value:
                bad = [f for f, v in p.items() if isinstance(v, dict) and v.get("points") == 0]
                if bad:
                    lost.append(f"{p.get('position')}: {', '.join(bad)}")
        elif isinstance(value, dict) and value.get("points") == 0:
            lost.append(f"{key} (got {str(value.get('got'))[:40]})")
    return lost


for run in sys.argv[1:]:
    status = json.loads(sh("atira", "status", run, "--json") or "{}")
    score = status.get("score") or {}
    ev = events(run)
    count = collections.Counter(d.get("event") for d in ev)
    print(f"\n=== {run}: quality {score.get('quality')} · eligible {score.get('eligible')} · "
          f"{(score.get('duration_ms') or 0) / 1000:.0f} s · ${(status.get('cost_micro_usd') or 0) / 1e6:.4f} · "
          f"{status.get('calls')} calls · state {status.get('status') or status.get('state')}")
    if score.get("breakdown"):
        print("  lost:", "; ".join(lost_points(score["breakdown"])) or "nothing")
    if ev:
        print(f"  log window {ev[0].get('t')}–{ev[-1].get('t')} s · hedges {count['llm_hedge']} "
              f"(twin won {sum(1 for d in ev if d.get('event') == 'llm_hedge_won' and d.get('by') == 'twin')}) · "
              f"llm errors {count['llm_error']} · goto failed {count['goto_failed']} · tab recoveries {count['tab_recovered']}")
    for d in ev:
        e = d.get("event")
        if e in ("mission_status", "evidence_phase_error", "no_bid_recheck", "no_bid_recheck_done", "review_check",
                 "submit_phase_done", "tab_recovery_limit", "exit"):
            print("  ", d.get("t"), e, {k: str(v)[:140] for k, v in d.items()
                                        if k not in ("t", "event", "verified", "status", "missions", "kinds", "digest")})
        if e == "evidence_done":
            print("  ", d.get("t"), "evidence_done digest:", json.dumps(d.get("digest"), ensure_ascii=False)[:900])
        if e == "trace" and any(w in str(d.get("line")) for w in ("no_bid", "WARNING", "not found", "fitting=[]")):
            print("   trace:", str(d.get("line"))[:160])
        if e == "answer":
            print("  ", d.get("t"), "answer skipped:", d.get("skipped"))
    errors = collections.Counter(str(d.get("error", ""))[:50] for d in ev if d.get("event") in ("llm_error", "goto_error"))
    if errors:
        print("  errors:", dict(errors.most_common(4)))

